<?php
require_once __DIR__.'/lib/auth.php';requireAuth();$pdo=db();$user=currentUser();$jobId=(int)($_GET['job_id']??0);$jobs=$pdo->prepare("SELECT DISTINCT j.id,j.title FROM interview_batches ib JOIN jobs j ON j.id=ib.job_id WHERE ib.created_by=? ORDER BY j.title");$jobs->execute([$user['id']]);$jobs=$jobs->fetchAll();$params=[$user['id']];$where=$jobId?' AND ib.job_id=?':'';if($jobId)$params[]=$jobId;$stmt=$pdo->prepare("SELECT ii.id,ii.status,ii.sent_at,ii.recipient_email,c.name candidate_name,j.title job_title,ib.availability_start,ib.availability_end,ib.timezone,s.starts_at,s.ends_at FROM interview_invitations ii JOIN interview_batches ib ON ib.id=ii.batch_id JOIN candidates c ON c.id=ii.candidate_id JOIN jobs j ON j.id=ib.job_id LEFT JOIN interview_slots s ON s.id=ii.confirmed_slot_id WHERE ib.created_by=?$where ORDER BY COALESCE(s.starts_at,CONCAT(ib.availability_start,' 23:59:59')),c.name");$stmt->execute($params);$items=$stmt->fetchAll();$confirmed=array_values(array_filter($items,fn($item)=>$item['status']==='confirmed'));$waiting=array_values(array_filter($items,fn($item)=>$item['status']==='awaiting_confirmation'));$activePage='pipeline';$pageTitle='Interview calendar · ResumeIQ';$pageStyles='<style>.calendar-head{padding:24px;display:flex;justify-content:space-between;align-items:center;gap:16px}.calendar-filter{min-width:240px}.calendar-grid{display:grid;grid-template-columns:1.25fr .75fr;gap:10px;margin-top:10px}.calendar-panel{padding:18px}.date-group{margin-top:16px}.date-group h3{font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.06em}.meeting,.waiting{border:1px solid var(--line);border-radius:9px;padding:13px;margin-top:8px}.meeting{border-left:4px solid var(--primary)}.meeting strong,.waiting strong{display:block}.meeting small,.waiting small{display:block;color:var(--muted);margin-top:4px}.waiting-list{max-height:650px;overflow:auto}.status-count{display:inline-flex;padding:5px 8px;border-radius:7px;background:var(--primary-soft);color:var(--primary);font-weight:700}@media(max-width:900px){.calendar-grid{grid-template-columns:1fr}.calendar-head{align-items:flex-start;flex-direction:column}.calendar-filter{width:100%}}</style>';require __DIR__.'/views/partials/header.php';$byDate=[];foreach($confirmed as $item)$byDate[substr($item['starts_at'],0,10)][]=$item;
?>
<section class="panel calendar-head"><div><div class="kicker"><i class="fa-regular fa-calendar-check"></i> Interview calendar</div><h1>Confirmed interviews</h1><p>Confirmed slots are locked. Awaiting candidates remain visible separately until their one-time link is used or expires.</p></div><form class="calendar-filter"><select class="control" name="job_id" onchange="this.form.submit()"><option value="0">All job profiles</option><?php foreach($jobs as $job):?><option value="<?=(int)$job['id']?>" <?=(int)$job['id']===$jobId?'selected':''?>><?=htmlspecialchars($job['title'])?></option><?php endforeach?></select></form></section>
<section class="calendar-grid"><article class="panel calendar-panel"><h2>Schedule <span class="status-count"><?=count($confirmed)?> confirmed</span></h2><?php foreach($byDate as $date=>$meetings):?><section class="date-group"><h3><?=htmlspecialchars(date('l, d F Y',strtotime($date)))?></h3><?php foreach($meetings as $meeting):?><div class="meeting"><strong><?=htmlspecialchars(date('g:i A',strtotime($meeting['starts_at'])))?> · <?=htmlspecialchars($meeting['candidate_name'])?></strong><small><?=htmlspecialchars($meeting['job_title'])?> · <?=htmlspecialchars($meeting['recipient_email'])?> · <?=htmlspecialchars($meeting['timezone'])?></small></div><?php endforeach?></section><?php endforeach?><?php if(!$confirmed):?><div class="empty">No confirmed interviews for this filter.</div><?php endif?></article><aside class="panel calendar-panel waiting-list"><h2>Awaiting confirmation <span class="status-count"><?=count($waiting)?></span></h2><?php foreach($waiting as $item):?><div class="waiting"><strong><?=htmlspecialchars($item['candidate_name'])?></strong><small><?=htmlspecialchars($item['job_title'])?></small><small>Window <?=htmlspecialchars(date('d M',strtotime($item['availability_start'])))?>–<?=htmlspecialchars(date('d M Y',strtotime($item['availability_end'])))?></small></div><?php endforeach?><?php if(!$waiting):?><div class="empty">No candidates awaiting confirmation.</div><?php endif?></aside></section>
<?php require __DIR__.'/views/partials/footer.php';
